// M3.1 — File transfer UI (CEA2.x protocol, decision 6 D6.5: Tauri-only).
// Renders the QR code generated by the Rust backend and shows share status.
// No browser fallback — file transfer requires Tauri (TLS server, filesystem).

import QRCode from 'qrcode';
import { invoke } from './tauri-bridge.js';

function tauriAvailable() {
  return typeof window !== 'undefined' &&
         Boolean(window.__TAURI__) &&
         Boolean(window.__TAURI__?.core?.invoke);
}

/** Toast helper (reuses the global #toast element). */
function toast(msg) {
  const el = document.getElementById('toast');
  if (!el) return;
  el.textContent = msg;
  el.classList.add('show');
  clearTimeout(toast._timer);
  toast._timer = setTimeout(() => el.classList.remove('show'), 3000);
}

export function setupFileTransfer() {
  const btn = document.getElementById('ft-open');
  const dialog = document.getElementById('ft-dialog');
  const closeBtn = document.getElementById('ft-close');
  const startBtn = document.getElementById('ft-start');
  const stopBtn = document.getElementById('ft-stop');
  const qrCanvas = document.getElementById('ft-qr-canvas');
  const infoPanel = document.getElementById('ft-info');
  const emptyPanel = document.getElementById('ft-empty');
  const errorPanel = document.getElementById('ft-error');
  const countdownEl = document.getElementById('ft-countdown');
  const filesEl = document.getElementById('ft-files');
  const serverEl = document.getElementById('ft-server');
  const fingerprintEl = document.getElementById('ft-fingerprint');
  const pickList = document.getElementById('ft-pick-list');
  const fileCount = document.getElementById('ft-file-count');
  const addFileBtn = document.getElementById('ft-add-file');
  const resetFilesBtn = document.getElementById('ft-reset-files');

  if (!btn || !dialog) return;

  // Enable button only in Tauri mode (decision 6 D6.5: Tauri-only).
  if (tauriAvailable()) {
    btn.disabled = false;
  }

  let countdownTimer = null;
  let pollTimer = null;

  // ─── Dialog open/close ───
  btn.addEventListener('click', () => {
    dialog.showModal();
    refreshStatus();
  });

  closeBtn?.addEventListener('click', () => {
    dialog.close();
  });

  dialog.addEventListener('close', () => {
    clearInterval(countdownTimer);
    clearInterval(pollTimer);
  });

  // ─── Start share ───
  startBtn?.addEventListener('click', async () => {
    if (!tauriAvailable()) {
      toast('文件传输仅在桌面应用模式下可用');
      return;
    }
    startBtn.disabled = true;
    startBtn.textContent = '正在生成…';
    errorPanel.hidden = true;

    try {
      const shareInfo = await invoke('ft_start_share');
      renderShare(shareInfo);
      startPolling(shareInfo.end_time);
    } catch (e) {
      errorPanel.textContent = `启动分享失败: ${e}`;
      errorPanel.hidden = false;
      startBtn.disabled = false;
      startBtn.textContent = '开始分享';
    }
  });

  // ─── Stop share ───
  stopBtn?.addEventListener('click', async () => {
    stopBtn.disabled = true;
    try {
      await invoke('ft_stop_share');
    } catch (e) {
      // Ignore — local state clear is the main goal.
    }
    clearInterval(countdownTimer);
    clearInterval(pollTimer);
    showEmpty();
    stopBtn.disabled = false;
  });

  // ─── Connection status sync (control panel indicator) ───
  const connStatusEl = document.getElementById('ft-conn-status');
  function updateConnStatus(text) {
    if (connStatusEl) connStatusEl.textContent = text;
  }

  // ─── Render share info + QR ───
  function renderShare(info) {
    emptyPanel.hidden = true;
    infoPanel.hidden = false;
    startBtn.hidden = true;
    stopBtn.hidden = false;
    updateConnStatus(`分享中 · ${info.local_ip}:${info.port}`);

    // Render QR code from the JSON string.
    if (qrCanvas && info.qr_json) {
      QRCode.toCanvas(qrCanvas, info.qr_json, {
        width: 256,
        margin: 1,
        color: { dark: '#0c1013', light: '#ffffff' },
        errorCorrectionLevel: 'M',
      }, (err) => {
        if (err) {
          errorPanel.textContent = `QR 码生成失败: ${err}`;
          errorPanel.hidden = false;
        }
      });
    }

    // Server info.
    if (serverEl) {
      serverEl.textContent = `${info.local_ip}:${info.port}`;
    }

    // Certificate fingerprint (truncated for display).
    if (fingerprintEl) {
      const fp = info.cert_sha256 || '';
      fingerprintEl.textContent = fp.length > 16
        ? `${fp.slice(0, 8)}…${fp.slice(-8)}`
        : fp;
      fingerprintEl.title = fp;
    }

    // File list.
    if (filesEl) {
      filesEl.innerHTML = '';
      for (const f of info.files) {
        const li = document.createElement('li');
        const sizeKB = (f.size / 1024).toFixed(1);
        li.innerHTML = `<span class="ft-file-name">${f.name}</span>
          <span class="ft-file-meta">${sizeKB} KB · ${f.kind}</span>`;
        filesEl.appendChild(li);
      }
    }
  }

  // ─── Countdown timer ───
  function startPolling(endTime) {
    clearInterval(countdownTimer);
    clearInterval(pollTimer);

    const updateCountdown = () => {
      const now = Math.floor(Date.now() / 1000);
      const remaining = endTime - now;
      if (countdownEl) {
        if (remaining > 0) {
          const m = Math.floor(remaining / 60);
          const s = remaining % 60;
          countdownEl.textContent = `剩余 ${m}:${String(s).padStart(2, '0')}`;
          countdownEl.classList.remove('expired');
        } else {
          countdownEl.textContent = '已过期';
          countdownEl.classList.add('expired');
          clearInterval(countdownTimer);
          clearInterval(pollTimer);
        }
      }
    };
    updateCountdown();
    countdownTimer = setInterval(updateCountdown, 1000);

    // Poll for status changes (e.g., session claimed).
    pollTimer = setInterval(async () => {
      try {
        const status = await invoke('ft_get_status');
        if (!status) {
          // Share ended (e.g., stopped or expired).
          showEmpty();
        }
      } catch {
        // Ignore poll errors.
      }
    }, 3000);
  }

  // ─── Show empty state ───
  function showEmpty() {
    emptyPanel.hidden = false;
    infoPanel.hidden = true;
    startBtn.hidden = false;
    stopBtn.hidden = true;
    startBtn.disabled = false;
    startBtn.textContent = '开始分享';
    errorPanel.hidden = true;
    updateConnStatus('未启动');
    if (qrCanvas) {
      const ctx = qrCanvas.getContext('2d');
      ctx?.clearRect(0, 0, qrCanvas.width, qrCanvas.height);
    }
    refreshFileList();
  }

  // ─── File list management (pre-share) ───
  async function refreshFileList() {
    if (!tauriAvailable()) return;
    try {
      const files = await invoke('ft_get_files');
      renderPickList(files);
    } catch {
      // Service not ready yet — show empty list.
      renderPickList([]);
    }
  }

  function renderPickList(files) {
    if (!pickList) return;
    pickList.innerHTML = '';

    if (fileCount) fileCount.textContent = String(files.length);
    if (startBtn) startBtn.disabled = files.length === 0;

    if (files.length === 0) {
      const li = document.createElement('li');
      li.className = 'ft-file-empty-hint';
      li.textContent = '暂无文件，点击「添加文件」或放入默认目录';
      pickList.appendChild(li);
      return;
    }

    for (const f of files) {
      const li = document.createElement('li');
      const sizeKB = (f.size / 1024).toFixed(1);
      li.innerHTML = `<div class="ft-file-info">
          <span class="ft-file-name">${f.name}</span>
          <span class="ft-file-meta">${sizeKB} KB · ${f.kind}</span>
        </div>
        <button class="ft-file-remove" data-id="${f.file_id}" title="移除" aria-label="移除 ${f.name}">×</button>`;
      pickList.appendChild(li);
    }

    // Attach remove handlers.
    pickList.querySelectorAll('.ft-file-remove').forEach(btn => {
      btn.addEventListener('click', async () => {
        const id = btn.dataset.id;
        try {
          const files = await invoke('ft_remove_file', { fileId: id });
          renderPickList(files);
        } catch (e) {
          toast(`移除失败: ${e}`);
        }
      });
    });
  }

  addFileBtn?.addEventListener('click', async () => {
    if (!tauriAvailable()) {
      toast('文件选择仅在桌面应用模式下可用');
      return;
    }
    addFileBtn.disabled = true;
    try {
      const files = await invoke('ft_pick_files');
      renderPickList(files);
    } catch (e) {
      toast(`选择文件失败: ${e}`);
    }
    addFileBtn.disabled = false;
  });

  resetFilesBtn?.addEventListener('click', async () => {
    if (!tauriAvailable()) return;
    try {
      const files = await invoke('ft_reset_files');
      renderPickList(files);
    } catch (e) {
      toast(`重置失败: ${e}`);
    }
  });

  // ─── Check existing share on dialog open ───
  async function refreshStatus() {
    if (!tauriAvailable()) {
      emptyPanel.querySelector('p').textContent =
        '文件传输仅在桌面应用模式下可用。请在 Tauri 模式下运行 (cargo tauri dev)。';
      updateConnStatus('仅桌面');
      return;
    }

    try {
      const status = await invoke('ft_get_status');
      if (status) {
        renderShare(status);
        startPolling(status.end_time);
      } else {
        showEmpty();
      }
    } catch (e) {
      // ft_get_status might fail if service isn't initialized.
      showEmpty();
    }
  }
}
